<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,Storage,DB};
use App\Models\{User,MarketingChannelConnection};
use App\Services\Marketing\MarketingPostQueue;
class MarketingPostQueueTest extends TestCase {
 use RefreshDatabase;
 private function fixture():array {
  Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);config(['marketing.post_queue_enabled'=>true,'marketing.post_scheduling_enabled'=>true,'marketing.social_publishing_enabled'=>true,'services.facebook.client_id'=>'queue-test','services.facebook.client_secret'=>'test','marketing.execution_enabled'=>false]);Storage::fake('local');Storage::fake('public');$im=imagecreatetruecolor(10,10);ob_start();imagejpeg($im);Storage::disk('public')->put('queue.jpg',ob_get_clean());imagedestroy($im);$prod=\App\Models\Product::create(['title'=>'Queue fixture','handle'=>'queue-fixture','status'=>'active','base_price'=>1]);$im=\App\Models\ProductImage::create(['product_id'=>$prod->id,'path'=>'queue.jpg','position'=>0]);$c=MarketingChannelConnection::create(['merchant_key'=>app(\App\Services\Marketing\MarketingChannels::class)->merchant(),'platform'=>'facebook','provider_account_id'=>'123','app_id'=>'queue-test','name'=>'Test page','access_token'=>'PRIVATE','permissions'=>['pages_show_list','pages_read_engagement','pages_manage_posts'],'tasks'=>['CREATE_CONTENT'],'authorized_by'=>$u->id,'state'=>'connected']);return ['id'=>(string)\Illuminate\Support\Str::uuid(),'version'=>0,'copy'=>'Queue acceptance test','title'=>'Queue test','asset'=>'image:'.$im->id,'type'=>'Post','targets'=>[$c->id],'copies'=>[],'options'=>[],'tz'=>'Asia/Kuala_Lumpur'];
 }
 public function test_web_accepts_without_provider_and_job_publishes_once(){ $p=$this->fixture();$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Queued');Http::assertNothingSent();$this->assertDatabaseCount('marketing_post_dispatches',1);$this->assertDatabaseCount('jobs',1);$id=DB::table('marketing_post_dispatches')->value('id');Http::fake(['*/123/photos'=>Http::response(['id'=>'photo-1','post_id'=>'123_post-1'])]);app(MarketingPostQueue::class)->run($id);app(MarketingPostQueue::class)->run($id);Http::assertSentCount(1);$this->getJson('/admin/marketing/posts/data')->assertJsonPath('posts.0.status','Published'); }
 public function test_due_sweep_is_idempotent_and_legacy_schedules_are_not_adopted(){ $p=$this->fixture();$p['due']=now()->addHour()->toIso8601String();$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk()->assertJsonPath('post.status','Scheduled');$q=app(MarketingPostQueue::class);$this->assertSame(0,$q->sweep());$this->assertDatabaseCount('jobs',0);$this->travel(61)->minutes();$this->assertSame(1,$q->sweep());$this->assertSame(0,$q->sweep());$this->assertDatabaseCount('jobs',1);Http::assertNothingSent(); }
 public function test_cancelled_schedule_and_changed_account_never_publish(){ $p=$this->fixture();$p['due']=now()->addHour()->toIso8601String();$r=$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk();$this->postJson('/admin/marketing/posts/data/cancel',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();$this->travel(61)->minutes();app(MarketingPostQueue::class)->sweep();$this->assertDatabaseCount('jobs',0);Http::assertNothingSent(); }

 public function test_changed_connection_or_media_stops_before_provider(){ $p=$this->fixture();$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$id=DB::table('marketing_post_dispatches')->value('id');MarketingChannelConnection::findOrFail($p['targets'][0])->increment('version');app(MarketingPostQueue::class)->run($id);Http::assertNothingSent();$this->assertDatabaseHas('marketing_post_dispatches',['id'=>$id,'state'=>'attention','error_code'=>'review_required']);$this->getJson('/admin/marketing/posts/data')->assertJsonPath('posts.0.status','Needs attention'); }
 public function test_modified_source_hash_stops_before_provider(){ $p=$this->fixture();$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();Storage::disk('public')->put('queue.jpg','changed');app(MarketingPostQueue::class)->run(DB::table('marketing_post_dispatches')->value('id'));Http::assertNothingSent();$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'attention']); }
 public function test_executing_job_preserves_one_approval_and_locks_cancellation(){ $p=$this->fixture();$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$due=$r->json('post.due');$blocked=false;Http::fake(function()use($p,&$blocked){$row=\App\Models\MarketingPost::findOrFail($p['id']);try{app(\App\Services\Marketing\MarketingPosts::class)->write($row->user_id,'cancel',['id'=>$row->id,'version'=>$row->version]);}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$blocked=$e->getStatusCode()===409;}return Http::response(['id'=>'photo','post_id'=>'123_post']);});app(MarketingPostQueue::class)->run(DB::table('marketing_post_dispatches')->value('id'));$this->assertTrue($blocked);$this->getJson('/admin/marketing/posts/data')->assertJsonCount(1,'posts.0.approvals')->assertJsonPath('posts.0.due',$due);Http::assertSentCount(1); }
 public function test_edited_schedule_invalidates_old_revision_and_dispatches_only_new_approval(){ $p=$this->fixture();$p['due']=now()->addHour()->toIso8601String();$r=$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk();$p['version']=$r->json('post.version');$p['copy']='Changed text';$r=$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk();$p['version']=$r->json('post.version');$p['due']=now()->addHours(2)->toIso8601String();$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk();$this->travel(61)->minutes();$this->assertSame(0,app(MarketingPostQueue::class)->sweep());$this->travel(61)->minutes();$this->assertSame(1,app(MarketingPostQueue::class)->sweep());$this->assertDatabaseCount('jobs',1);$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'superseded']);Http::assertNothingSent(); }
 public function test_unknown_initial_submission_is_not_automatically_repeated(){ $p=$this->fixture();$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$id=DB::table('marketing_post_dispatches')->value('id');Http::fake(['*/123/photos'=>Http::response([],503)]);$q=app(MarketingPostQueue::class);$q->run($id);$q->run($id);$this->travel(20)->minutes();$q->sweep();$this->assertDatabaseHas('marketing_post_dispatches',['id'=>$id,'state'=>'attention']);Http::assertSentCount(1); }
 public function test_staff_and_revoked_owner_cannot_execute_publishing(){ $p=$this->fixture();$owner=auth()->id();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>false]);$u->permissions()->create(['permission'=>'marketing.view']);$u->permissions()->create(['permission'=>'marketing.edit']);$this->actingAs($u);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertForbidden();$this->actingAs(User::findOrFail($owner));$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();User::whereKey($owner)->update(['is_super_admin'=>false]);app(MarketingPostQueue::class)->run(DB::table('marketing_post_dispatches')->value('id'));Http::assertNothingSent();$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'attention']); }
 public function test_queue_configuration_failure_rolls_back_approval_and_job(){ $p=$this->fixture();config(['queue.connections.marketing-posts.driver'=>'sync']);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(500);$this->assertDatabaseCount('marketing_posts',0);$this->assertDatabaseCount('marketing_post_dispatches',0);$this->assertDatabaseCount('jobs',0);Http::assertNothingSent(); }
 public function test_queue_uses_saved_utc_instant_and_does_not_adopt_legacy_rows(){ $p=$this->fixture();$p['due']=now()->addDay()->setTimezone('America/New_York')->toIso8601String();$r=$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk();$this->assertSame(\Carbon\CarbonImmutable::parse($p['due'])->utc()->timestamp,\Carbon\CarbonImmutable::parse($r->json('post.due'))->timestamp);$this->assertSame('Asia/Kuala_Lumpur',$r->json('post.tz'));DB::table('marketing_post_dispatches')->delete();$this->travel(2)->days();$this->assertSame(0,app(MarketingPostQueue::class)->sweep());$this->assertDatabaseCount('jobs',0);Http::assertNothingSent(); }

 public function test_real_database_queue_worker_executes_only_the_marketing_job(){ $p=$this->fixture();$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();Http::fake(['*/123/photos'=>Http::response(['id'=>'photo-1','post_id'=>'123_post-1'])]);$this->artisan('queue:work',['connection'=>'marketing-posts','--queue'=>'marketing-posts','--once'=>true,'--tries'=>1,'--sleep'=>0])->assertExitCode(0);$this->assertDatabaseCount('jobs',0);$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'completed']);Http::assertSentCount(1); }
 public function test_second_image_change_invalidates_the_whole_approved_selection(){ $p=$this->fixture();$image=\App\Models\ProductImage::first();Storage::disk('public')->put('second.jpg',Storage::disk('public')->get('queue.jpg'));$second=\App\Models\ProductImage::create(['product_id'=>$image->product_id,'path'=>'second.jpg','position'=>1]);$p['assets']=[$p['asset'],'image:'.$second->id];$p['format']='carousel';$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();Storage::disk('public')->put('second.jpg','changed');app(MarketingPostQueue::class)->run(DB::table('marketing_post_dispatches')->value('id'));Http::assertNothingSent();$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'attention']); }
 public function test_approved_multi_image_dispatch_produces_only_one_post(){ $p=$this->fixture();$image=\App\Models\ProductImage::first();$second=\App\Models\ProductImage::create(['product_id'=>$image->product_id,'path'=>'queue.jpg','position'=>1]);$p['assets']=[$p['asset'],'image:'.$second->id];$p['format']='carousel';$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$n=0;Http::fake(function($r)use(&$n){return Http::response(str_ends_with($r->url(),'/photos')?['id'=>'photo'.++$n]:['id'=>'123_456']);});$id=DB::table('marketing_post_dispatches')->value('id');$q=app(MarketingPostQueue::class);$q->run($id);$q->run($id);Http::assertSentCount(3);$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'completed']);$this->assertDatabaseCount('marketing_post_attempts',1); }
 public function test_partial_success_is_not_reposted_when_remaining_destination_is_confirmed_again(){ $p=$this->fixture();$first=MarketingChannelConnection::findOrFail($p['targets'][0]);$second=$first->replicate();$second->provider_account_id='456';$second->save();$p['targets'][]=$second->id;$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();Http::fake(['*/123/photos'=>Http::response(['id'=>'one','post_id'=>'123_one']),'*/456/photos'=>Http::sequence()->push(['error'=>['code'=>190]],400)->push(['id'=>'two','post_id'=>'456_two'])]);$q=app(MarketingPostQueue::class);$q->run(DB::table('marketing_post_dispatches')->value('id'));$row=\App\Models\MarketingPost::findOrFail($p['id']);$this->assertSame('Published',$row->document['outcomes'][$first->id]['status']);$p['version']=$row->version;$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$q->run(DB::table('marketing_post_dispatches')->where('state','queued')->value('id'));Http::assertSentCount(3);$this->assertSame('Published',\App\Models\MarketingPost::findOrFail($p['id'])->status); }
 public function test_known_photo_task_is_reconciled_in_background_without_new_submission(){ $p=$this->fixture();\Illuminate\Support\Facades\URL::forceRootUrl('https://shop.example');\Illuminate\Support\Facades\URL::forceScheme('https');config(['services.tiktok.client_id'=>'tk','marketing.external_video_publishing_enabled'=>true,'marketing.tiktok_photo_verified_prefix'=>'https://shop.example/marketing/post-delivery/']);MarketingChannelConnection::findOrFail($p['targets'][0])->update(['platform'=>'tiktok','app_id'=>'tk','permissions'=>['user.info.basic','video.publish'],'expires_at'=>now()->addHour()]);$p['options'][$p['targets'][0]]=['privacy'=>'SELF_ONLY','allow_comment'=>false,'commercial'=>false,'your_brand'=>false,'branded'=>false,'terms'=>true];$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();Http::assertNothingSent();Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['privacy_level_options'=>['SELF_ONLY'],'comment_disabled'=>true],'error'=>['code'=>'ok']]),'*/content/init/'=>Http::response(['data'=>['publish_id'=>'known-photo'],'error'=>['code'=>'ok']]),'*/status/fetch/'=>Http::sequence()->push(['data'=>['status'=>'PROCESSING_UPLOAD'],'error'=>['code'=>'ok']])->push(['data'=>['status'=>'PUBLISH_COMPLETE'],'error'=>['code'=>'ok']])]);$q=app(MarketingPostQueue::class);$id=DB::table('marketing_post_dispatches')->value('id');$q->run($id);$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'waiting_result']);$this->travel(31)->seconds();$this->assertSame(1,$q->sweep());$q->run($id);$q->run($id);$this->assertDatabaseHas('marketing_post_dispatches',['state'=>'completed']);Http::assertSentCount(4); }

 public function test_stale_worker_is_query_only_and_never_restarts_upload(){ $p=$this->fixture();$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$id=DB::table('marketing_post_dispatches')->value('id');DB::table('marketing_post_dispatches')->where('id',$id)->update(['state'=>'executing','updated_at'=>now()->subMinutes(16)]);$q=app(MarketingPostQueue::class);$q->sweep();$this->assertDatabaseHas('marketing_post_dispatches',['id'=>$id,'state'=>'waiting_result']);$this->travel(3)->minutes();$q->sweep();$q->run($id);$q->run($id);Http::assertNothingSent();$this->assertDatabaseHas('marketing_post_dispatches',['id'=>$id,'state'=>'attention']); }
 public function test_worker_failure_after_recorded_success_does_not_downgrade_or_repeat(){ $p=$this->fixture();$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk();$id=DB::table('marketing_post_dispatches')->value('id');Http::fake(['*/123/photos'=>Http::response(['id'=>'one','post_id'=>'123_one'])]);$q=app(MarketingPostQueue::class);$q->run($id);DB::table('marketing_post_dispatches')->where('id',$id)->update(['state'=>'executing']);$q->quarantine($id);$this->assertDatabaseHas('marketing_post_dispatches',['id'=>$id,'state'=>'completed']);$this->assertSame('Published',\App\Models\MarketingPost::findOrFail($p['id'])->status);Http::assertSentCount(1); }
}
